"""Rebuild the HTML PRD from the canonical Markdown without extra dependencies."""
import html
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def inline(text):
    text = html.escape(text)
    return re.sub(r"\*\*(.*?)\*\*", r"<strong>\1</strong>", text)


def build():
    lines = (ROOT / "PRD-v2.md").read_text().splitlines()
    parts, toc = [], []
    in_table = False
    for line in lines:
        if not line.startswith("|") and in_table:
            parts.append("</tbody></table></div>")
            in_table = False
        if line.startswith("# "):
            continue
        if line.startswith("需求说明书"):
            continue
        if line.startswith("## "):
            title = line[3:]
            anchor = "s" + str(len(toc) + 1)
            toc.append(f'<a href="#{anchor}">{inline(title)}</a>')
            parts.append(f'<h2 id="{anchor}">{inline(title)}</h2>')
        elif line.startswith("### ") or re.match(r"^FR-\d+", line):
            title = line[4:] if line.startswith("### ") else line
            anchor = re.match(r"FR-\d+", title)
            attr = f' id="{anchor.group()}"' if anchor else ""
            parts.append(f"<h3{attr}>{inline(title)}</h3>")
            if anchor:
                demos = {
                    "FR-01": '<div class="demo"><b>交互示意 · 登录</b><label>用户名<input value="reviewer" id="demo-user"></label><label>密码<input type="password" placeholder="输入至少 8 位" id="demo-pass"></label><button data-demo="login">登录工作台</button><p class="feedback" id="login-feedback" aria-live="polite"></p></div>',
                    "FR-02": '<div class="demo"><b>规模示意 · 一次选择全班作品</b><label>学生分支数<input id="demo-count" type="range" min="2" max="100" value="50"></label><p id="count-feedback">50 个作品 → 1,225 个作品对，每个无序对只比较一次。</p><a href="http://127.0.0.1:8765">打开平台，运行 50 分支真实引擎示例 ↗</a></div>',
                    "FR-04": '<div class="demo"><b>交互示意 · 批次生命周期</b><p id="stage-feedback">排队中 · 等待资源</p><button data-demo="stage">下一阶段</button><button data-demo="fail" class="secondary">模拟单作品失败</button><button data-demo="retry" class="secondary">重新分析</button></div>',
                    "FR-05": '<div class="demo"><b>口径示意 · 非真实检测数据</b><label>A 中匹配 token 数（A 总量 100）<input id="demo-coverage" type="range" min="0" max="100" value="60"></label><p id="coverage-feedback">A→B 60% · B→A 30% · 整体 40%（B 总量 200）</p></div>',
                    "FR-06": '<div class="demo"><b>矩阵示意 · 非真实检测数据</b><p>同一对作品：原始整体覆盖 80%，扣除教师模板后 20%。失败作品显示 N/A，不能按 0% 解读。</p><button data-demo="scope">切换口径</button><p id="scope-feedback">当前：原始 80%</p></div>',
                    "FR-07": '<div class="demo"><b>交互示意 · 按需证据</b><label>按路径筛选<input id="demo-filter" placeholder="输入 utils 或不存在的路径"></label><button data-demo="evidence" id="demo-pair">utils.js ↔ helpers.js · 查看片段</button><p id="filter-feedback" aria-live="polite"></p><div id="demo-code" hidden><p>标识符变化 · A 第 1 行 ↔ B 第 1 行</p><div class="demo-grid"><pre>const total = price * count;</pre><pre>const sum = cost * quantity;</pre></div></div></div>',
                    "FR-08": '<div class="demo"><b>交互示意 · 批次历史</b><button data-demo="history">查看 50 分支示意任务</button><p id="history-feedback" aria-live="polite"></p></div>',
                    "FR-09": '<div class="demo"><b>交互示意 · 导出与打印</b><p>正式报告包含匹配源码，请按仓库权限分享。此按钮打印当前需求说明书。</p><button data-demo="print">打印 / 保存当前 PRD</button></div>',
                    "FR-10": '<div class="demo"><b>真实功能入口</b><p>平台中的 50 分支示例使用模拟源码运行检测引擎，包含教师模板、改名作品组和仅含模板的空作品。此 PRD 的交互仅为说明。</p><a href="http://127.0.0.1:8765">登录平台体验 ↗</a></div>',
                }
                if anchor.group() in demos:
                    parts.append(demos[anchor.group()])
        elif line.startswith("|"):
            cells = [c.strip() for c in line.strip("|").split("|")]
            if all(re.fullmatch(r"[-: ]+", c) for c in cells):
                continue
            if not in_table:
                parts.append('<div class="table-wrap"><table><thead><tr>' +
                             "".join(f"<th>{inline(c)}</th>" for c in cells) +
                             "</tr></thead><tbody>")
                in_table = True
            else:
                parts.append("<tr>" + "".join(f"<td>{inline(c)}</td>" for c in cells) + "</tr>")
        elif line.strip():
            parts.append(f"<p>{inline(line)}</p>")
    page = """<!-- Generated by Trae Work -->
<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CodeLens · 产品需求说明书</title>
<style>
@font-face{font-family:Instrument;src:url('./_shared/fonts/InstrumentSans-Regular.ttf')}@font-face{font-family:Instrument;src:url('./_shared/fonts/InstrumentSans-Bold.ttf');font-weight:700}@font-face{font-family:JetBrains;src:url('./_shared/fonts/JetBrainsMono-Regular.ttf')}
:root{--bg:#f7f9fc;--bg2:#ffffff;--ink:#1d2939;--muted:#526174;--rule:#dce3ee;--accent:#3159d8;--accent2:#097f79;--wash:rgba(49,89,216,.08);--glass:rgba(255,255,255,.8);--font:Instrument,-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;--mono:JetBrains,monospace}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:28px}body{margin:0;background:radial-gradient(at 10% 0,var(--wash),transparent 50%),var(--bg);color:var(--ink);font:16px/1.85 var(--font)}a{color:var(--accent)}aside{position:fixed;top:0;bottom:0;width:250px;padding:40px 26px;border-right:1px solid var(--rule);background:var(--glass);backdrop-filter:blur(10px)}aside b{font-size:23px}aside small{display:block;color:var(--muted);margin:6px 0 26px}aside a{display:block;text-decoration:none;margin:16px 0;color:var(--muted);font-size:14px}main{margin-left:250px;padding:56px 6vw 100px;max-width:1450px}header{border-bottom:1px solid var(--rule);padding-bottom:35px}.eyebrow{font-size:13px;letter-spacing:.1em;color:var(--accent);font-weight:700}h1{font-size:46px;line-height:1.3;margin:16px 0}h2{font-size:28px;margin-top:64px;border-bottom:1px solid var(--rule);padding-bottom:12px}h3{font-size:21px;margin-top:34px}p{margin:15px 0}header p{color:var(--muted)}.tags{display:flex;gap:12px;flex-wrap:wrap}.tags span{background:var(--wash);color:var(--accent);padding:3px 12px;border-radius:20px;font-size:13px}.table-wrap{overflow-x:auto;overflow-y:auto;max-height:600px;margin:22px 0;border:1px solid var(--rule);border-radius:10px}table{width:100%;border-collapse:collapse;background:var(--bg2);font-size:14px}th,td{text-align:left;padding:13px 16px;border-bottom:1px solid var(--rule);vertical-align:top}th{background:var(--wash);font-weight:700;position:sticky;top:0}td:first-child{min-width:120px}tr:last-child td{border:0}.demo{background:var(--glass);backdrop-filter:blur(10px);border:1px solid var(--rule);border-radius:12px;padding:22px;margin:20px 0}.demo>b{font-size:13px;color:var(--accent)}.demo label{display:block;font-size:14px;margin:14px 0}.demo input{display:block;width:100%;margin:8px 0;border:1px solid var(--rule);border-radius:6px;padding:10px;color:var(--ink);background:var(--bg2);font:inherit}.demo button{padding:10px 16px;border:0;border-radius:6px;background:linear-gradient(135deg,var(--accent),var(--accent2));color:var(--bg2);font:600 14px var(--font);cursor:pointer;margin:6px 6px 6px 0}.demo button.secondary{background:var(--wash);color:var(--accent)}.demo-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.feedback{color:var(--accent);font-size:14px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.8 var(--mono);background:var(--wash);padding:15px;border-radius:8px}.note{background:var(--wash);border-left:3px solid var(--accent);padding:16px;color:var(--muted);font-size:14px}footer{margin-top:55px;color:var(--muted);font-size:13px}
@media(max-width:900px){aside{position:relative;width:auto;padding:20px;border-right:0;border-bottom:1px solid var(--rule)}aside nav{display:none}aside small{margin:0}main{margin:0;padding:28px 20px}h1{font-size:34px}.demo-grid{grid-template-columns:1fr}table{min-width:680px}}@media print{aside,.demo{display:none}main{margin:0;padding:0}h2{break-before:page}.table-wrap{overflow:visible;max-height:none}body{background:var(--bg2)}}
</style></head><body><aside><b>⌘ CodeLens</b><small>产品需求说明书 · v1.0</small><nav>__TOC__</nav></aside><main><header><div class="eyebrow">产品定义 / 2026.10.24</div><h1>看见代码之间的联系。</h1><p>代码相似性分析平台 · 从两个 Git 版本，到可解释的匹配证据。</p><div class="tags"><span>多语言查重</span><span>分支比对</span><span>HTML 报告</span></div></header><p class="note">依据用户需求编写。标为 [Assumption, TBD] 的值是可调整的首版假设；相似覆盖比例不等于抄袭概率。下方交互均为需求示意，不是实际检测结果。</p>__BODY__<footer>CodeLens PRD v1.0 · Markdown 为维护来源 · 离线可阅读</footer></main><script src="./_shared/js/echarts.min.js"></script><script src="assets/demos.js"></script></body></html>"""
    target = ROOT / "prd" / "prd.html"
    page = page.replace("v1.0", "v2.0").replace("看见代码之间的联系。", "全班作品，一次复核。").replace("代码相似性分析平台 · 从两个 Git 版本，到可解释的匹配证据。", "毕业实习作品批量查重 · 同仓库 2–100 个分支 · 模板扣除与按需证据。").replace("<span>分支比对</span>", "<span>批量矩阵</span><span>教师模板扣除</span>")
    target.write_text(page.replace("__TOC__", "".join(toc)).replace("__BODY__", "\n".join(parts)))
    print(target)


if __name__ == "__main__":
    build()
